const request = $json.body;
const errors = [];

const cuisines = ['german', 'italian', 'japanese', 'indian', 'gourmet', 'fusion'];
const diets = ['vegetarian', 'vegan', 'keto', 'none'];
const times = ['quick', 'medium', 'complex'];
const languages = ['en', 'de'];

// An unknown language is not worth an error, English is the safe fallback.
request.language = languages.includes(request.language) ? request.language : 'en';

// Same limits as the form, so nothing long or odd reaches the prompt.
const units = ['g', 'ml', 'piece'];
const usable = (item) =>
  typeof item?.name === 'string' &&
  item.name.trim() !== '' &&
  item.name.length <= 40 &&
  item.amount > 0 &&
  units.includes(item.unit);

const list = request.ingredients;
if (!Array.isArray(list) || list.length === 0) {
  errors.push('Add at least one ingredient.');
} else if (list.length > 20) {
  errors.push('Add at most 20 ingredients.');
} else if (!list.every(usable)) {
  errors.push('Every ingredient needs a name of up to 40 characters, an amount and a unit.');
}

if (!Number.isInteger(request.portions) || request.portions < 1 || request.portions > 12) {
  errors.push('Portions must be between 1 and 12.');
}

if (!Number.isInteger(request.helpers) || request.helpers < 1 || request.helpers > 3) {
  errors.push('Cooks must be between 1 and 3.');
}

if (!times.includes(request.cookingTime)) {
  errors.push('Unknown cooking time.');
}

if (!cuisines.includes(request.cuisine)) {
  errors.push('Unknown cuisine.');
}

if (!diets.includes(request.diet)) {
  errors.push('Unknown diet.');
}

if (errors.length > 0) {
  return [{ json: { valid: false, error: errors[0] } }];
}

return [{ json: { valid: true, request } }];

// Cloudflare fronts n8n Cloud and overwrites cf-connecting-ip, so that header cannot
// be faked. Without it, read x-forwarded-for from the left and skip the proxies.
const PRIVATE = [
  /^10\./, /^127\./, /^192\.168\./, /^172\.(1[6-9]|2\d|3[01])\./,
  /^169\.254\./, /^0\./, /^100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\./,
  /^::1$/, /^f[cd]/, /^fe[89ab]/,
];

// Brackets, a trailing port and the IPv4 mapping would split one visitor over two rows.
function clean(value) {
  const text = String(value).trim().toLowerCase();
  const bracketed = text.match(/^\[(.+?)\](?::\d+)?$/);
  const bare = bracketed ? bracketed[1] : text.replace(/^((?:\d{1,3}\.){3}\d{1,3}):\d+$/, '$1');
  return bare.startsWith('::ffff:') ? bare.slice(7) : bare;
}

// Must look like an address and belong to someone outside, or the database rejects it.
function isVisitor(value) {
  const v4 = /^(\d{1,3}\.){3}\d{1,3}$/.test(value);
  const v6 = value.includes(':') && /^[0-9a-f:]+$/.test(value);
  return (v4 || v6) && !PRIVATE.some((range) => range.test(value));
}

const headers = $('Webhook').item.json.headers ?? {};
const edge = clean(headers['cf-connecting-ip'] ?? '');
const chain = String(headers['x-forwarded-for'] ?? '').split(',').map(clean);
const ip = isVisitor(edge) ? edge : (chain.find(isVisitor) ?? '127.0.0.1');

return [{ json: { ip, request: $json.request } }];

// Turns the request into one clear order for the model.
const request = $('Read visitor address').item.json.request;
const list = request.ingredients
  .map((item) => `${item.amount} ${item.unit} ${item.name}`)
  .join(', ');

const language =
  request.language === 'de'
    ? 'Schreibe jeden Titel und jeden Text auf Deutsch, auch die Zutatennamen, unabhaengig von der Kochrichtung.'
    : 'Write every title and every text in English, whatever the cooking style is.';

const prompt = [
  'You are a cooking assistant. Create exactly three different recipes.',
  `Ingredients at home: ${list}.`,
  `Portions: ${request.portions}. Cooks in the kitchen: ${request.helpers}.`,
  `Cooking style: ${request.cuisine}. Diet: ${request.diet}.`,
  `Time frame: ${request.cookingTime} (quick is up to 20 minutes, medium 20 to 45, complex over 45).`,
  'Every recipe uses at least 70 percent of the ingredients above.',
  'Every recipe may add at most three basic extra ingredients.',
  'The three recipes differ in preparation or taste.',
  'Scale all amounts to the number of portions.',
  'Steps are chronological. Mark steps that run in parallel and give each step a cook.',
  'Use waiting times, for example time in the oven, for other steps.',
  'Give durations in minutes and nutrition per portion and for the whole recipe.',
  language,
].join(' ');

return [{ json: { prompt } }];

// Recipe shape already fixes three recipes with at most three extras.
// A schema cannot check how many of the visitor's ingredients are used.
const recipes = ($json.output ?? $json).recipes;
const wanted = $('Read visitor address').item.json.request.ingredients;

// "Chicken breast" and "sliced chicken breasts" mean the same thing here.
const plain = (name) => name.toLowerCase().replace(/[^\p{L} ]/gu, '').trim();
const same = (mine, theirs) => {
  const a = plain(mine);
  const b = plain(theirs);
  return a !== '' && b !== '' && (a.includes(b) || b.includes(a));
};

const tooFew = recipes.find((recipe) => {
  const listed = [...recipe.yourIngredients, ...recipe.extraIngredients];
  const used = wanted.filter((item) => listed.some((entry) => same(item.name, entry.name)));
  return used.length / wanted.length < 0.7;
});

if (tooFew) {
  return [{ json: { rulesOk: false, error: `"${tooFew.title}" uses too few of the ingredients.` } }];
}

return [{ json: { rulesOk: true, recipes } }];

// The database uses snake_case columns, the app uses camelCase.
const request = $('Read visitor address').item.json.request;

const rows = $json.recipes.map((recipe) => ({
  title: recipe.title,
  cuisine: request.cuisine,
  diet: request.diet,
  language: request.language,
  cooking_time: request.cookingTime,
  cooking_minutes: recipe.cookingMinutes,
  portions: request.portions,
  helpers: request.helpers,
  your_ingredients: recipe.yourIngredients,
  extra_ingredients: recipe.extraIngredients,
  steps: recipe.steps,
  nutrition_per_portion: recipe.nutritionPerPortion,
  nutrition_total: recipe.nutritionTotal,
}));

return [{ json: { rows } }];
